/** Exact new Moonmoth hookup inverse to complete frozen063 sources; no local history dependency. */
import assert from 'node:assert/strict';import{createHash}from'node:crypto';
const hash=s=>createHash('sha256').update(s).digest('hex');const normalize=s=>s.replace(/(from\s*['"]\.\/[^'"?\n]+)(?:\?[^'"\n]*)?(['"])/g,'$1$2');
export function priorMoonmothMain(source){let s=normalize(source);const pattern=/^[ \t]*\/\/ MOONMOTH_MAIN_BEGIN\n[\s\S]*?^[ \t]*\/\/ MOONMOTH_MAIN_END\n/gm,blocks=s.match(pattern)||[];assert.equal(blocks.length,5);assert.equal(hash(blocks.join('')),"fd86b43457b1914ac4d4cbbb8836dbb23441bc688365fc0eac3f1a359c3142bc");s=s.replace(pattern,'');for(const line of ["...(moonmothHabitat?.captureOccluders||[]),", "moonmoth:3.6,", "result.item.species==='moonmoth'?'夜の林縁・道沿いの細い枝':", "...(moonmothHabitat?.colliders||[]),"]){assert.equal(s.split(line).length-1,1);s=s.replace(line,'');}assert.equal(hash(s),"6c8306ffc5639e79d74f99c839fea1136795d1aefef58743d0517d9014b1b827");return s;}
export function priorMoonmothModel(source){let s=normalize(source);const pattern=/^[ \t]*\/\/ MOONMOTH_MODEL_BEGIN\n[\s\S]*?^[ \t]*\/\/ MOONMOTH_MODEL_END\n/gm,blocks=s.match(pattern)||[];assert.equal(blocks.length,3);assert.equal(hash(blocks.join('')),"580c92ac01d91ed1354f8195230e33e8e5fe1425ad210dde0741c08a10a720fd");s=s.replace(pattern,'');for(const line of []){assert.equal(s.split(line).length-1,1);s=s.replace(line,'');}assert.equal(hash(s),"1732582561374aa7129ad826df1413ec0c9f0c4e5e712494b8a96b42d701e5ea");return s;}
